"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[3285],{6303(n,e,t){t.r(e),t.d(e,{assets:()=>c,contentTitle:()=>d,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>p});const o=JSON.parse('{"id":"part5-deep-learning-and-llms/cnn-pytorch-implementation","title":"Implementing CNNs in PyTorch: Conv2d, Modules, Dropout, and Shapes","description":"This tutorial turns the transcript into a practical, self-contained guide to building CNN models in PyTorch. You\u2019ll learn nn.Conv2d basics, how PyTorch uses modules and inheritance, when you need a custom model, how t...","source":"@site/docs/part5-deep-learning-and-llms/06-cnn-pytorch-implementation.mdx","sourceDirName":"part5-deep-learning-and-llms","slug":"/part5-deep-learning-and-llms/06-cnn-pytorch-implementation","permalink":"/tutorials/part5-deep-learning-and-llms/06-cnn-pytorch-implementation","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":6,"frontMatter":{"title":"Implementing CNNs in PyTorch: Conv2d, Modules, Dropout, and Shapes","slug":"/part5-deep-learning-and-llms/06-cnn-pytorch-implementation","description":"This tutorial turns the transcript into a practical, self-contained guide to building CNN models in PyTorch. You\u2019ll learn nn.Conv2d basics, how PyTorch uses modules and inheritance, when you need a custom model, how t...","sidebar_label":"6. CNN PyTorch implementation","pagination_label":"6. CNN PyTorch implementation","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"5. CNN architecture","permalink":"/tutorials/part5-deep-learning-and-llms/05-cnn-architecture"},"next":{"title":"7. CNN dropout and train/eval","permalink":"/tutorials/part5-deep-learning-and-llms/07-cnn-dropout-train-eval"}}');var a=t(4848),i=t(8453),s=t(8172);const l=JSON.parse('{"sourcePath":"part5-deep-learning-and-llms/06-cnn-pytorch-implementation.html","route":"/part5-deep-learning-and-llms/06-cnn-pytorch-implementation","kind":"chapter","partId":"part5","partLabel":"Part V - Deep Learning & Large Language Models","accent":"coral","heading":"PyTorch CNN Coding Prep: Conv2d, Custom nn.Module, Dropout, and Convolution Arithmetic","title":"Implementing CNNs in PyTorch: Conv2d, Modules, Dropout, and Shapes","description":"This tutorial turns the transcript into a practical, self-contained guide to building CNN models in PyTorch. You\u2019ll learn nn.Conv2d basics, how PyTorch uses modules and inheritance, when you need a custom model, how t...","readingMinutes":8,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-nn-conv2d-essentials-what-you-must-know-before-coding-cnns","label":"1) nn.Conv2d essentials (what you must know before coding CNNs)"},{"id":"2-pytorch-everything-is-a-module-inheritance-and-composition","label":"2) PyTorch \u201ceverything is a module\u201d: inheritance and composition"},{"id":"3-sequential-vs-custom-models-when-to-use-which","label":"3) Sequential vs Custom Models: when to use which"},{"id":"4-a-cnn-model-skeleton-two-clean-ways","label":"4) A CNN model skeleton (two clean ways)"},{"id":"5-dropout-regularization-the-real-behavior-clearly-explained","label":"5) Dropout regularization (the real behavior, clearly explained)"},{"id":"6-convolution-arithmetic-compute-output-sizes-so-your-linear-layer-matches","label":"6) Convolution arithmetic (compute output sizes so your Linear layer matches)"},{"id":"cheat-sheet-what-to-remember","label":"Cheat sheet: what to remember"}],"html":"<div class=\\"wrap\\">\\n\\n  <header>\\n    \\n    <p>\\n      This tutorial turns the transcript into a practical, self-contained guide to\\n      <b>building CNN models in PyTorch</b>. You\u2019ll learn <code>nn.Conv2d</code> basics,\\n      how PyTorch uses <b>modules and inheritance</b>, when you need a <b>custom model</b>,\\n      how to handle <b>flattening between conv and dense layers</b>,\\n      how <b>dropout really works</b>, and how to compute output sizes with\\n      <b>convolution arithmetic</b>.\\n    </p>\\n\\n    <div class=\\"chips\\">\\n      <span class=\\"chip\\">Conv2d arguments</span>\\n      <span class=\\"chip\\">Modules &amp; inheritance</span>\\n      <span class=\\"chip\\">Sequential vs custom models</span>\\n      <span class=\\"chip\\">Flatten/view</span>\\n      <span class=\\"chip\\">Dropout (train vs eval)</span>\\n      <span class=\\"chip\\">Output-size formulas</span>\\n    </div>\\n\\n    <nav>\\n      <a href=\\"#conv2d\\">1) Conv2d essentials</a>\\n      <a href=\\"#modules\\">2) Modules &amp; inheritance</a>\\n      <a href=\\"#sequential-vs-custom\\">3) Sequential vs custom</a>\\n      <a href=\\"#cnn-skeleton\\">4) CNN skeleton</a>\\n      <a href=\\"#dropout\\">5) Dropout (real behavior)</a>\\n      <a href=\\"#conv-arithmetic\\">6) Convolution arithmetic</a>\\n      <a href=\\"#cheatsheet\\">Cheat sheet</a>\\n    </nav>\\n  </header>\\n\\n  <section id=\\"conv2d\\">\\n    <h2 id=\\"1-nn-conv2d-essentials-what-you-must-know-before-coding-cnns\\">1) <code>nn.Conv2d</code> essentials (what you must know before coding CNNs)</h2>\\n\\n    <p>\\n      In PyTorch, the standard convolution layer for images is <code>torch.nn.Conv2d</code>.\\n      It\u2019s \u201c2D\u201d because the convolution slides over the <b>spatial axes</b> (height and width).\\n      The color/channel axis is handled as \u201cchannels,\u201d not as a spatial direction.\\n    </p>\\n\\n    <div class=\\"callout\\">\\n      <p style=\\"margin:0;\\">\\n        <b>Key idea:</b> A Conv2d layer learns a set of filters (kernels).\\n        Each filter produces one output channel (one feature map).\\n      </p>\\n    </div>\\n\\n    <h3 id=\\"pytorch-tensor-layout-important\\">PyTorch tensor layout (important!)</h3>\\n    <p>\\n      PyTorch uses the <b>NCHW</b> layout for images:\\n    </p>\\n    <ul>\\n      <li><b>N</b> = batch size</li>\\n      <li><b>C</b> = channels (e.g., 3 for RGB)</li>\\n      <li><b>H</b> = height</li>\\n      <li><b>W</b> = width</li>\\n    </ul>\\n    <p class=\\"muted\\">\\n      Many tutorials talk about images as H\xd7W\xd7C; that\u2019s fine conceptually, but in PyTorch code you\u2019ll usually use N\xd7C\xd7H\xd7W.\\n    </p>\\n\\n    <h3 id=\\"nn-conv2d-signature-the-arguments-you-ll-use-most\\"><code>nn.Conv2d</code> signature (the arguments you\u2019ll use most)</h3>\\n    <p>\\n      The common form is:\\n      \\\\[\\n        \\\\mathrm{Conv2d}(\\\\text{in\\\\_channels},\\\\ \\\\text{out\\\\_channels},\\\\ \\\\text{kernel\\\\_size},\\\\ \\\\text{stride},\\\\ \\\\text{padding})\\n      \\\\]\\n    </p>\\n\\n    <table>\\n      <thead>\\n        <tr><th>Argument</th><th>Meaning</th><th>Rule of thumb</th></tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td><code>in_channels</code></td>\\n          <td>Number of input channels</td>\\n          <td>RGB images \u2192 3. Later layers \u2192 number of feature maps from previous conv.</td>\\n        </tr>\\n        <tr>\\n          <td><code>out_channels</code></td>\\n          <td>Number of output channels (feature maps)</td>\\n          <td>Often grows: 32 \u2192 64 \u2192 128 \u2192 \u2026</td>\\n        </tr>\\n        <tr>\\n          <td><code>kernel_size</code></td>\\n          <td>Filter size (usually square)</td>\\n          <td>Usually odd: 3, 5, 7 (3 is most common in modern CNNs).</td>\\n        </tr>\\n        <tr>\\n          <td><code>stride</code></td>\\n          <td>Step size for sliding the kernel</td>\\n          <td>Stride 1 keeps resolution (with padding), stride 2 downsamples.</td>\\n        </tr>\\n        <tr>\\n          <td><code>padding</code></td>\\n          <td>Zeros added around image border</td>\\n          <td>Often chosen to preserve size (common \u201csame-like\u201d behavior).</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <h3 id=\\"what-does-the-learned-weight-tensor-look-like\\">What does the learned weight tensor look like?</h3>\\n    <p>\\n      Internally, the conv weights form a 4D tensor:\\n      \\\\[\\n        W \\\\in \\\\mathbb{R}^{C_\\\\text{out} \\\\times C_\\\\text{in} \\\\times K_h \\\\times K_w}\\n      \\\\]\\n    </p>\\n    <p>\\n      That is: one kernel per output channel, and each kernel spans <b>all input channels</b>.\\n      This matches the transcript idea: \u201ckernel is 4D: input channels, output channels, height, width.\u201d\\n      (PyTorch stores it as out\xd7in\xd7kh\xd7kw.)\\n    </p>\\n\\n    <div class=\\"codewrap\\">\\n      <div class=\\"codebar\\">\\n        <span class=\\"label\\">python \u2022 inspect Conv2d parameters</span>\\n        \\n      </div>\\n<pre class=\\"language-python\\"><code>import torch\\nimport torch.nn as nn\\n\\nconv = nn.Conv2d(in_channels=3, out_channels=16, kernel_size=3, stride=1, padding=1)\\n\\nprint(\\"weight shape:\\", conv.weight.shape)  # (out_channels, in_channels, kH, kW)\\nprint(\\"bias shape:\\", conv.bias.shape)      # (out_channels,)</code></pre>\\n    </div>\\n\\n    <h3 id=\\"why-conv2d-and-not-conv1d-conv3d\\">Why Conv2d and not Conv1d / Conv3d?</h3>\\n    <ul>\\n      <li><b>Conv1d</b>: sequences / time signals (e.g., audio, sensor streams).</li>\\n      <li><b>Conv2d</b>: images (height &amp; width are the spatial axes).</li>\\n      <li><b>Conv3d</b>: volumes (e.g., medical CT \u201cvoxels\u201d) or videos (height, width, time).</li>\\n    </ul>\\n\\n    <figure>\\n      <img alt=\\"Convolution animation\\" src=\\"/tutorials/images/external/2D_Convolution_Animation-240e665e01.gif\\">\\n      <figcaption>\\n        2D convolution animation (Wikimedia Commons):\\n        <a href=\\"https://commons.wikimedia.org/wiki/File:2D_Convolution_Animation.gif\\" target=\\"_blank\\" rel=\\"noopener\\">2D_Convolution_Animation.gif</a>\\n      </figcaption>\\n    </figure>\\n  </section>\\n\\n  <section id=\\"modules\\">\\n    <h2 id=\\"2-pytorch-everything-is-a-module-inheritance-and-composition\\">2) PyTorch \u201ceverything is a module\u201d: inheritance and composition</h2>\\n\\n    <p>\\n      PyTorch neural network building blocks are <b>modules</b> (instances of <code>nn.Module</code>).\\n      A Linear layer is a module. A ReLU is a module. A Sequential container is also a module.\\n      And your entire model is a module too.\\n    </p>\\n\\n    <div class=\\"callout\\">\\n      <p style=\\"margin:0;\\">\\n        <b>Superpower:</b> modules compose hierarchically.\\n        You can build a \u201cmodule of modules,\u201d then use it like a single module, and repeat.\\n      </p>\\n    </div>\\n\\n    <h3 id=\\"inheritance-why-your-custom-model-subclasses-nn-module\\">Inheritance (why your custom model subclasses <code>nn.Module</code>)</h3>\\n    <p>\\n      To create your own model class, you inherit from <code>nn.Module</code>.\\n      Two key pieces:\\n    </p>\\n    <ol>\\n      <li><b><code>__init__</code></b>: define submodules as attributes (layers you want to learn / run).</li>\\n      <li><b><code>forward</code></b>: define the computation (how data flows through layers).</li>\\n    </ol>\\n\\n    <div class=\\"codewrap\\">\\n      <div class=\\"codebar\\">\\n        <span class=\\"label\\">python \u2022 minimal custom MLP (Linear \u2192 ReLU \u2192 Linear)</span>\\n        \\n      </div>\\n<pre class=\\"language-python\\"><code>import torch\\nimport torch.nn as nn\\n\\nclass TinyMLP(nn.Module):\\n    def __init__(self, d_in: int, d_hidden: int, d_out: int):\\n        super().__init__()\\n        self.fc1 = nn.Linear(d_in, d_hidden)\\n        self.act = nn.ReLU()\\n        self.fc2 = nn.Linear(d_hidden, d_out)\\n\\n    def forward(self, x):\\n        x = self.fc1(x)\\n        x = self.act(x)\\n        x = self.fc2(x)\\n        return x\\n\\nmodel = TinyMLP(d_in=10, d_hidden=32, d_out=3)\\nx = torch.randn(5, 10)\\nlogits = model(x)\\nprint(logits.shape)  # (5, 3)</code></pre>\\n    </div>\\n\\n    <p class=\\"muted\\">\\n      Notice the key correspondence: defining layers in <code>__init__</code>, applying them in <code>forward</code>.\\n    </p>\\n  </section>\\n\\n  <section id=\\"sequential-vs-custom\\">\\n    <h2 id=\\"3-sequential-vs-custom-models-when-to-use-which\\">3) Sequential vs Custom Models: when to use which</h2>\\n\\n    <div class=\\"grid two\\">\\n      <div class=\\"callout\\">\\n        <h3 style=\\"margin:0 0 6px;\\" id=\\"option-a-nn-sequential\\">Option A \u2014 <code>nn.Sequential</code></h3>\\n        <p style=\\"margin:0;\\">\\n          Great when your network is just a straight stack of layers (no branching, no multi-input/output).\\n        </p>\\n      </div>\\n      <div class=\\"callout\\">\\n        <h3 style=\\"margin:0 0 6px;\\" id=\\"option-b-custom-nn-module\\">Option B \u2014 Custom <code>nn.Module</code></h3>\\n        <p style=\\"margin:0;\\">\\n          Needed when you must do operations not easily represented as a simple list of layers\\n          (reshapes, multiple paths, skip connections, multi-input/output, etc.).\\n        </p>\\n      </div>\\n    </div>\\n\\n    <h3 id=\\"why-custom-models-matter-in-cnns\\">Why custom models matter in CNNs</h3>\\n    <p>\\n      The classic \u201cboundary\u201d in CNNs is:\\n      <b>convolution outputs an image tensor</b> (N\xd7C\xd7H\xd7W), but\\n      <b>dense layers expect vectors</b> (N\xd7D).\\n      You need a reshape/flatten step in between.\\n    </p>\\n\\n    <ul>\\n      <li>Modern PyTorch provides <code>nn.Flatten()</code>.</li>\\n      <li>But you should still know how to do it manually with <code>x.view(...)</code> or <code>torch.flatten</code>.</li>\\n    </ul>\\n\\n    <div class=\\"codewrap\\">\\n      <div class=\\"codebar\\">\\n        <span class=\\"label\\">python \u2022 Flatten boundary: N\xd7C\xd7H\xd7W \u2192 N\xd7(C\xb7H\xb7W)</span>\\n        \\n      </div>\\n<pre class=\\"language-python\\"><code>import torch\\nx = torch.randn(8, 64, 7, 7)         # (N, C, H, W)\\nflat1 = x.view(x.size(0), -1)        # (N, C*H*W)\\nflat2 = torch.flatten(x, start_dim=1)\\n\\nprint(flat1.shape, flat2.shape)      # both: (8, 3136)</code></pre>\\n    </div>\\n\\n    <h3 id=\\"exercise-recommended\\">Exercise (recommended)</h3>\\n    <p>\\n      Recreate a tiny version of <code>nn.Sequential</code>:\\n      store modules, then call them in order in <code>forward</code>.\\n      This is a great way to lock in \u201cmodules + forward pass\u201d thinking.\\n    </p>\\n  </section>\\n\\n  <section id=\\"cnn-skeleton\\">\\n    <h2 id=\\"4-a-cnn-model-skeleton-two-clean-ways\\">4) A CNN model skeleton (two clean ways)</h2>\\n\\n    <p>\\n      A practical CNN typically has:\\n      <span class=\\"pill\\">Conv stack</span> \u2192 <span class=\\"pill\\">Flatten</span> \u2192 <span class=\\"pill\\">Dense stack</span>.\\n    </p>\\n\\n    <h3 id=\\"way-1-custom-model-with-two-sequential-blocks-explicit-view\\">Way 1: Custom model with two Sequential blocks + explicit view</h3>\\n    <div class=\\"codewrap\\">\\n      <div class=\\"codebar\\">\\n        <span class=\\"label\\">python \u2022 CNN as nn.Module (conv Sequential + view + dense Sequential)</span>\\n        \\n      </div>\\n<pre class=\\"language-python\\"><code>import torch\\nimport torch.nn as nn\\n\\nclass SimpleCNN(nn.Module):\\n    def __init__(self, num_classes: int = 10):\\n        super().__init__()\\n\\n        self.conv = nn.Sequential(\\n            nn.Conv2d(3, 32, kernel_size=3, stride=1, padding=1),\\n            nn.ReLU(),\\n            nn.Conv2d(32, 64, kernel_size=3, stride=2, padding=1),  # downsample\\n            nn.ReLU(),\\n        )\\n\\n        # We must know the flattened size here (see convolution arithmetic below).\\n        # For example: if input is (3, 32, 32), output after conv might be (64, 16, 16)\\n        # so flattened = 64*16*16 = 16384\\n        self.fc = nn.Sequential(\\n            nn.Linear(64 * 16 * 16, 256),\\n            nn.ReLU(),\\n            nn.Linear(256, num_classes),\\n        )\\n\\n    def forward(self, x):\\n        x = self.conv(x)\\n        x = x.view(x.size(0), -1)  # flatten\\n        x = self.fc(x)\\n        return x\\n\\nmodel = SimpleCNN(num_classes=10)\\ndummy = torch.randn(4, 3, 32, 32)\\nprint(model(dummy).shape)  # (4, 10)</code></pre>\\n    </div>\\n\\n    <h3 id=\\"way-2-pure-sequential-using-nn-flatten\\">Way 2: Pure Sequential using <code>nn.Flatten()</code></h3>\\n    <p class=\\"muted\\">\\n      This is cleaner, but you still need the correct input size for the first Linear layer.\\n    </p>\\n\\n    <div class=\\"codewrap\\">\\n      <div class=\\"codebar\\">\\n        <span class=\\"label\\">python \u2022 CNN as nn.Sequential (using nn.Flatten)</span>\\n        \\n      </div>\\n<pre class=\\"language-python\\"><code>import torch\\nimport torch.nn as nn\\n\\nmodel = nn.Sequential(\\n    nn.Conv2d(3, 32, kernel_size=3, stride=1, padding=1),\\n    nn.ReLU(),\\n    nn.Conv2d(32, 64, kernel_size=3, stride=2, padding=1),\\n    nn.ReLU(),\\n    nn.Flatten(),\\n    nn.Linear(64 * 16 * 16, 256),\\n    nn.ReLU(),\\n    nn.Linear(256, 10),\\n)\\n\\ndummy = torch.randn(4, 3, 32, 32)\\nprint(model(dummy).shape)  # (4, 10)</code></pre>\\n    </div>\\n\\n    <h3 id=\\"a-practical-trick-compute-the-flatten-size-automatically\\">A practical trick: compute the flatten size automatically</h3>\\n    <p>\\n      If you don\u2019t want to do manual arithmetic while prototyping,\\n      you can run a dummy tensor through the conv stack inside <code>__init__</code>\\n      to infer the flatten dimension once.\\n    </p>\\n\\n    <div class=\\"codewrap\\">\\n      <div class=\\"codebar\\">\\n        <span class=\\"label\\">python \u2022 infer flatten size with a dummy forward pass</span>\\n        \\n      </div>\\n<pre class=\\"language-python\\"><code>import torch\\nimport torch.nn as nn\\n\\nclass AutoShapeCNN(nn.Module):\\n    def __init__(self, input_shape=(3, 32, 32), num_classes=10):\\n        super().__init__()\\n        self.conv = nn.Sequential(\\n            nn.Conv2d(3, 32, 3, padding=1),\\n            nn.ReLU(),\\n            nn.Conv2d(32, 64, 3, stride=2, padding=1),\\n            nn.ReLU(),\\n        )\\n\\n        with torch.no_grad():\\n            dummy = torch.zeros(1, *input_shape)\\n            out = self.conv(dummy)\\n            flat_dim = out.view(1, -1).size(1)\\n\\n        self.head = nn.Sequential(\\n            nn.Flatten(),\\n            nn.Linear(flat_dim, 256),\\n            nn.ReLU(),\\n            nn.Linear(256, num_classes),\\n        )\\n\\n    def forward(self, x):\\n        x = self.conv(x)\\n        x = self.head(x)\\n        return x\\n\\nmodel = AutoShapeCNN()\\nprint(model(torch.randn(2, 3, 32, 32)).shape)  # (2, 10)</code></pre>\\n    </div>\\n\\n    <p class=\\"muted\\">\\n      This \u201cdummy pass\u201d trick is widely used during research/prototyping.\\n      You still should learn the arithmetic, but this keeps you productive.\\n    </p>\\n  </section>\\n\\n  <section id=\\"dropout\\">\\n    <h2 id=\\"5-dropout-regularization-the-real-behavior-clearly-explained\\">5) Dropout regularization (the real behavior, clearly explained)</h2>\\n\\n    <div class=\\"callout\\">\\n      <p style=\\"margin:0;\\">\\n        <b>Dropout does NOT permanently remove a neuron.</b>\\n        It applies a <b>fresh random mask each forward pass in training mode</b>,\\n        zeroing some activations temporarily.\\n      </p>\\n    </div>\\n\\n    <h3 id=\\"core-math-inverted-dropout\\">Core math (inverted dropout)</h3>\\n    <p>\\n      Let \\\\(h\\\\) be a layer activation vector/tensor. Sample a mask:\\n      \\\\[\\n        m_i \\\\sim \\\\mathrm{Bernoulli}(q),\\\\quad q = 1-p\\n      \\\\]\\n      Apply:\\n      \\\\[\\n        \\\\tilde{h} = \\\\frac{m \\\\odot h}{q}\\n      \\\\]\\n      This scaling keeps the expected magnitude consistent between train and eval.\\n    </p>\\n\\n    <h3 id=\\"what-happens-to-gradients\\">What happens to gradients?</h3>\\n    <p>\\n      The derivative wrt activations is:\\n      \\\\[\\n        \\\\frac{\\\\partial \\\\tilde{h}}{\\\\partial h} = \\\\frac{m}{q}\\n      \\\\]\\n      So if a unit is dropped (\\\\(m=0\\\\)), its gradient is 0 for that sample. Next batch, the mask changes, so it can update again.\\n    </p>\\n\\n    <h3 id=\\"train-vs-eval-mode-must-know\\">Train vs eval mode (must-know)</h3>\\n    <ul>\\n      <li><code>model.train()</code> \u2192 dropout active (random masks)</li>\\n      <li><code>model.eval()</code> \u2192 dropout disabled (identity)</li>\\n    </ul>\\n\\n    <div class=\\"codewrap\\">\\n      <div class=\\"codebar\\">\\n        <span class=\\"label\\">python \u2022 verify dropout randomness in train vs stability in eval</span>\\n        \\n      </div>\\n<pre class=\\"language-python\\"><code>import torch\\nimport torch.nn as nn\\n\\ndrop = nn.Dropout(p=0.5)\\nx = torch.ones(1, 10)\\n\\ndrop.train()\\ny1 = drop(x)\\ny2 = drop(x)\\n\\ndrop.eval()\\ny3 = drop(x)\\ny4 = drop(x)\\n\\nprint(\\"train outputs differ:\\", not torch.allclose(y1, y2))\\nprint(\\"eval outputs equal:\\", torch.allclose(y3, y4))</code></pre>\\n    </div>\\n\\n    <h3 id=\\"where-to-place-dropout-in-cnns\\">Where to place dropout in CNNs</h3>\\n    <p>\\n      The common default is to place dropout <b>between dense layers</b> (the classifier head),\\n      not inside convolution blocks. For conv feature maps, people sometimes use\\n      <code>nn.Dropout2d</code> (drops entire channels), but you should treat it as an experiment.\\n    </p>\\n\\n    <div class=\\"codewrap\\">\\n      <div class=\\"codebar\\">\\n        <span class=\\"label\\">python \u2022 typical dropout placement in a CNN head</span>\\n        \\n      </div>\\n<pre class=\\"language-python\\"><code>import torch.nn as nn\\n\\nhead = nn.Sequential(\\n    nn.Flatten(),\\n    nn.Linear(64*16*16, 256),\\n    nn.ReLU(),\\n    nn.Dropout(p=0.5),\\n    nn.Linear(256, 10),\\n)</code></pre>\\n    </div>\\n\\n    <figure>\\n      <img alt=\\"Dropout illustration\\" src=\\"/tutorials/images/external/Dropout_en-d57ec7c14c-fallback.svg\\">\\n      <figcaption>\\n        Local book diagram of dropout. Primary reference:\\n        <a href=\\"https://jmlr.org/papers/v15/srivastava14a.html\\" target=\\"_blank\\" rel=\\"noopener\\">Srivastava et al., 2014</a>.\\n      </figcaption>\\n    </figure>\\n  </section>\\n\\n  <section id=\\"conv-arithmetic\\">\\n    <h2 id=\\"6-convolution-arithmetic-compute-output-sizes-so-your-linear-layer-matches\\">6) Convolution arithmetic (compute output sizes so your Linear layer matches)</h2>\\n\\n    <p>\\n      CNNs become annoying to wire up when you reach the first dense layer, because you must know the flattened size.\\n      That requires knowing the conv output size.\\n    </p>\\n\\n    <h3 id=\\"the-pytorch-formula-per-spatial-dimension\\">The PyTorch formula (per spatial dimension)</h3>\\n    <p>\\n      For height (and similarly width), PyTorch effectively uses:\\n      \\\\[\\n        H_{\\\\text{out}} = \\\\left\\\\lfloor \\\\frac{H_{\\\\text{in}} + 2P - D\\\\,(K-1) - 1}{S} + 1 \\\\right\\\\rfloor\\n      \\\\]\\n    </p>\\n    <ul>\\n      <li>\\\\(H_\\\\text{in}\\\\): input height</li>\\n      <li>\\\\(K\\\\): kernel size (height)</li>\\n      <li>\\\\(S\\\\): stride</li>\\n      <li>\\\\(P\\\\): padding</li>\\n      <li>\\\\(D\\\\): dilation (usually 1 unless you set it)</li>\\n    </ul>\\n\\n    <div class=\\"callout\\">\\n      <p style=\\"margin:0;\\">\\n        <b>Common case:</b> dilation \\\\(D=1\\\\). Then:\\n        \\\\[\\n          H_{\\\\text{out}} = \\\\left\\\\lfloor \\\\frac{H_{\\\\text{in}} + 2P - K}{S} + 1 \\\\right\\\\rfloor\\n        \\\\]\\n      </p>\\n    </div>\\n\\n    <h3 id=\\"valid-vs-same-like-behavior\\">\u201cValid\u201d vs \u201cSame-like\u201d behavior</h3>\\n    <p>\\n      In classic terms (stride 1, dilation 1):\\n    </p>\\n    <ul>\\n      <li><b>Valid</b>: \\\\(P=0\\\\) \u2192 \\\\(H_\\\\text{out} = H_\\\\text{in} - K + 1\\\\)</li>\\n      <li><b>Same-like</b>: choose \\\\(P\\\\) to keep size when \\\\(S=1\\\\) (often \\\\(P=\\\\lfloor K/2\\\\rfloor\\\\) for odd kernels)</li>\\n    </ul>\\n\\n    <p class=\\"muted\\">\\n      In Keras you can write <code>padding=\\"same\\"</code>. In PyTorch you usually specify the numeric padding yourself\\n      (or in newer versions you may see padding strings in some APIs, but relying on the arithmetic is still essential).\\n    </p>\\n\\n    <h3 id=\\"worked-example-32-32-stride-2-16-16\\">Worked example: 32\xd732 \u2192 (stride 2) \u2192 16\xd716</h3>\\n    <p>\\n      Suppose:\\n      \\\\(H_\\\\text{in}=32\\\\), \\\\(K=3\\\\), \\\\(S=2\\\\), \\\\(P=1\\\\) (a common \u201csame-like downsample\u201d setting).\\n      Then:\\n      \\\\[\\n        H_{\\\\text{out}} = \\\\left\\\\lfloor \\\\frac{32 + 2(1) - 3}{2} + 1 \\\\right\\\\rfloor\\n        = \\\\left\\\\lfloor \\\\frac{31}{2} + 1 \\\\right\\\\rfloor\\n        = \\\\lfloor 15.5 + 1 \\\\rfloor\\n        = 16\\n      \\\\]\\n    </p>\\n\\n    <div class=\\"codewrap\\">\\n      <div class=\\"codebar\\">\\n        <span class=\\"label\\">python \u2022 helper to compute conv output size (H/W)</span>\\n        \\n      </div>\\n<pre class=\\"language-python\\"><code>import math\\n\\ndef conv_out_size(n_in, k, stride=1, pad=0, dilation=1):\\n    return math.floor((n_in + 2*pad - dilation*(k-1) - 1) / stride + 1)\\n\\nprint(conv_out_size(32, k=3, stride=2, pad=1))  # 16</code></pre>\\n    </div>\\n\\n    <h3 id=\\"why-odd-kernel-sizes-are-common\\">Why odd kernel sizes are common</h3>\\n    <p>\\n      With odd kernels (3,5,7\u2026), there is a clear \u201ccenter\u201d pixel. This makes it easy to do symmetric padding\\n      (e.g., \\\\(P=\\\\lfloor K/2\\\\rfloor\\\\)) and preserve alignment.\\n    </p>\\n\\n    <figure>\\n      <img alt=\\"Convolution arithmetic diagram\\" src=\\"/tutorials/images/external/Conv2d_padding_strides-3ef00e7b63-fallback.svg\\">\\n      <figcaption>\\n        Local book diagram of stride and padding. Technical reference:\\n        <a href=\\"https://arxiv.org/abs/1603.07285\\" target=\\"_blank\\" rel=\\"noopener\\">Dumoulin and Visin</a>.\\n      </figcaption>\\n    </figure>\\n\\n    <h3 id=\\"shortcut-if-you-hate-arithmetic\\">Shortcut if you hate arithmetic</h3>\\n    <p>\\n      During prototyping, use the \u201cdummy forward pass\u201d trick shown earlier to infer flatten size.\\n      But you still want the formula in your toolbox when reading papers or debugging shape errors.\\n    </p>\\n  </section>\\n\\n  <section id=\\"cheatsheet\\">\\n    <h2 id=\\"cheat-sheet-what-to-remember\\">Cheat sheet: what to remember</h2>\\n\\n    <table>\\n      <thead><tr><th>Topic</th><th>Remember this</th></tr></thead>\\n      <tbody>\\n        <tr>\\n          <td>Tensor layout</td>\\n          <td>PyTorch images are usually <b>N\xd7C\xd7H\xd7W</b>.</td>\\n        </tr>\\n        <tr>\\n          <td>Conv2d weights</td>\\n          <td><code>(out_channels, in_channels, kH, kW)</code></td>\\n        </tr>\\n        <tr>\\n          <td>Modules</td>\\n          <td>Layers/models are <code>nn.Module</code>; composition gives \u201cmodule of modules\u201d.</td>\\n        </tr>\\n        <tr>\\n          <td>Custom model</td>\\n          <td>Define layers in <code>__init__</code>, apply them in <code>forward</code>.</td>\\n        </tr>\\n        <tr>\\n          <td>Conv \u2192 Dense boundary</td>\\n          <td>Use <code>x.view(x.size(0), -1)</code> or <code>nn.Flatten()</code>.</td>\\n        </tr>\\n        <tr>\\n          <td>Dropout</td>\\n          <td>New random mask each forward pass in <code>train()</code>; disabled in <code>eval()</code>.</td>\\n        </tr>\\n        <tr>\\n          <td>Conv arithmetic</td>\\n          <td>\\\\( \\\\left\\\\lfloor \\\\frac{H + 2P - D(K-1) - 1}{S} + 1 \\\\right\\\\rfloor \\\\)</td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <p class=\\"muted small\\">\\n      Visual sources used: local assets with Wikimedia credits retained where applicable.\\n    </p>\\n  </section>\\n\\n</div>"}'),r={title:"Implementing CNNs in PyTorch: Conv2d, Modules, Dropout, and Shapes",slug:"/part5-deep-learning-and-llms/06-cnn-pytorch-implementation",description:"This tutorial turns the transcript into a practical, self-contained guide to building CNN models in PyTorch. You\u2019ll learn nn.Conv2d basics, how PyTorch uses modules and inheritance, when you need a custom model, how t...",sidebar_label:"6. CNN PyTorch implementation",pagination_label:"6. CNN PyTorch implementation",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},p=[];function h(n){return(0,a.jsx)(s.A,{content:l})}function u(n={}){const{wrapper:e}={...(0,i.R)(),...n.components};return e?(0,a.jsx)(e,{...n,children:(0,a.jsx)(h,{...n})}):h()}}}]);